add_scan_chains chain2 group1 indata4 testout4
Contents of atpg.testproc file:
timeplate gen_tp1 = force_pi 0 ;
measure_po 100 ;
pulse clk_ 200 100;
pulse tck 200 100;
pulse shift_clock 200 100;
pulse reset 200 100;
pulse refclk 200 100;
pulse ramclk 200 100;
period 400 ;
end;
procedure shift = scan_group grp1 ;
timeplate gen_tp1 ;
cycle = force_sci ;
measure_sco ;
pulse shift_clock ;
end;
end;
procedure load_unload = scan_group grp1 ;
timeplate gen_tp1 ;
cycle = force clk_ 0 ;
force reset 0;
force ramclk 0 ;
force scan_enable 1 ;
end ;
apply shift 16;
end;
procedure test_setup = scan_group grp1;
timeplate gen_tp1;
cycle = force test_logic_reset 1;
end;
cycle = force test_logic_reset 0;
end;
end;
