//     "      "    " output   edt_channels_out1      - 
//    Scan channel 2 input    edt_channels_in2       - 
//     "      "    " output   edt_channels_out2      - 
//

set_edt_pins clock a1
set_edt_pins bypass my_bypass -inv
report_edt_pins
