Example 13
This procedure file defines four events in the shift procedure (force_pi is set to occur at 5 ns 
rather than at the beginning of the cycle).
set time scale 1.000000 ns ;
set strobe_window time 1 ; 
 timeplate gen_tp1 =
    force_pi 5 ; 
    measure_po 10 ; 
    pulse CLOCK 20 10;
    period 40 ; 
 end;
 procedure shift =
    scan_group grp1 ;
    timeplate gen_tp1 ;
    // cycle 0 starts at time 0
    cycle =
        force_sci ;
        measure_sco ;
        pulse CLOCK ;
    end;
end;
procedure load_unload =
    scan_group grp1 ;
    timeplate gen_tp1 ;
    // cycle 0 starts at time 0
    cycle =
        force scan_en 1 ;
        force CLOCK 0 ;
    end ;
    apply shift 3;
 end;
 procedure test_setup =
    timeplate gen_tp1 ;
    // cycle 0 starts at time 0
    cycle =
        force IN1 0 ;
    end;
 end;
The report_gates command reports four values, one for each event in the cycle.
