Examples
Example 1
The following ICL module contains a circular path from the ScanMux “sibmux” to the 
ScanRegister “sibreg” and back to the ScanMux “sibmux”.
Module chip {
  TCKPort tck;
  ScanInPort si;
  ScanOutPort so { Source sibreg; }
  CaptureEnPort ce;
  UpdateEnPort ue;
  ShiftEnPort se;
  SelectPort sel;
  ResetPort rst;
  ScanRegister sibreg {
    ScanInSource sibmux;
    CaptureSource sibreg;
    ResetValue 1'b0;
  }
  ScanMux sibmux SelectedBy sibreg {
    1'b0 : tdr[0];
    1'b1 : sibreg;
  }
  ScanRegister tdr[7:0] {
    ScanInSource si;
    CaptureSource tdr;
    ResetValue 8'b0;
  }
}

