Example 2
This example shows how to deal with clock port cloning that may happen during layout. 
Imagine you had a clock port called clka on your core and after layout this clock port was split 
into eight ports where the original clock port drives a small percent of the original fanout and 
the seven new ports clka_1 to clka_7 drive the rest. You need to have this new clock toggling in 
the testbench whenever clka was toggling. The following example script takes the 
PatternsSpecification created by create_patterns_specification and clones the clka entry in all 
ClockPeriods wrapper it is already found. The new entries in the ClockPeriods wrapper tells 
process_patterns_specification to also start those clocks.
set spec [create_patterns_spec]
set new_clka_ports [get_name_list [get_ports clka_*]]
set ClockPeriods_wrappers [get_config_elements ClockPeriods -in $spec -hier]
foreach_in_collection ClockPeriods_wrapper $ClockPeriods_wrappers {
  if {[get_config_value clka -in $ClockPeriods_wrapper -exists]} {
    set period [get_config_value clka -in $ClockPeriods_wrapper]
    foreach new_clka_port $new_clka_ports {
      add_config_element $new_clka_port -in $ClockPeriods_wrapper -value $period
    }
  }
}
