    ClockPeriods {
      clk100 : 10ns ;
      clk150 : 6.66667ns ;
      clk200 : 5ns ;
    }
    TestStep (serial_load) {
      LogicBist {
        CoreInstance(CHIP) {
          run_mode      : run_time_prog ;
          begin_pattern : 0 ;
          end_pattern   : 7 ;
        }
      }
    }
    TestStep (diagnostic) {
      LogicBist {
        CoreInstance(CHIP) {
          run_mode      : run_time_prog ;
          begin_pattern : 7 ;
          end_pattern   : 7 ;
          DiagnosisOptions {
            extract_flop_data : on ;
