Examples
The following example shows the typical use of the DataInOutPort construct as part of the 
interface of a design with a TPSP controller.
Module chip {
    ClockPort SPCLK {
      Attribute function_modifier = "two_pin_serial_clock_port";
   }
   DataInOutPort SPIO { 
      Source tpsp_inst.spio_out;
      Attribute function_modifier = "two_pin_serial_inout_port";
   }
   Instance tpsp_inst Of tpsp_controller {
      InputPort spio_in = SPIO;
      InputPort spclk   = SPCLK;
      InputPort tdo     = block_inst.tdo;
